<?php
require dirname(__DIR__).'/app/bootstrap.php'; require_permission('settings.manage');
$defaults=[['type'=>'feature','title'=>'A little more room for thought.','text'=>'Curated ideas and thoughtful stories, presented with clarity.','button'=>'Explore stories','url'=>'#latest','image'=>'']];
$raw=setting('page_builder_blocks',''); $blocks=json_decode($raw,true); if(!is_array($blocks)) $blocks=$defaults;
$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=(string)($_POST['action']??'save');
 if($action==='reset') $blocks=$defaults; else {
  $types=['feature','text','image','cta']; $blocks=[];
  $titles=$_POST['title']??[]; $texts=$_POST['text']??[]; $typesIn=$_POST['type']??[]; $buttons=$_POST['button']??[]; $urls=$_POST['url']??[]; $images=$_POST['image']??[];
  for($i=0;$i<min(8,count($titles));$i++){
   $type=in_array(($typesIn[$i]??''),$types,true)?$typesIn[$i]:'text';
   $title=trim(strip_tags((string)$titles[$i])); $body=trim(strip_tags((string)($texts[$i]??''))); $button=trim(strip_tags((string)($buttons[$i]??''))); $url=trim((string)($urls[$i]??'')); $image=trim((string)($images[$i]??''));
   if($title==='' && $body==='') continue;
   if($url!=='' && !str_starts_with($url,'#') && !preg_match('~^https?://~i',$url) && !str_starts_with($url,'/')) $url='';
   if($image!=='' && !preg_match('~^(https?://|/)~i',$image)) $image='';
   $blocks[]=['type'=>$type,'title'=>text_substr($title,0,140),'text'=>text_substr($body,0,1200),'button'=>text_substr($button,0,80),'url'=>text_substr($url,0,500),'image'=>text_substr($image,0,500)];
  }
 }
 $q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)'); $q->execute(['page_builder_blocks',json_encode($blocks,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]); $notice='Homepage blocks saved.';
}
function pbv($v){return e((string)$v);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page Builder — NOWRD</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.builder{max-width:1000px;margin:40px auto;padding:24px}.builder-head{display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap}.builder-intro{color:var(--muted);max-width:660px;line-height:1.7}.block-card{border:1px solid var(--line);background:var(--paper,#fff);border-radius:18px;padding:20px;margin:16px 0;box-shadow:0 8px 28px #17233b0a}.block-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:flex;flex-direction:column;gap:6px;margin:8px 0}.field label{font-size:12px;font-weight:700;color:var(--muted)}.field input,.field textarea,.field select{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px;font:inherit;background:var(--surface,#fff);color:var(--ink)}.field textarea{min-height:100px;resize:vertical}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.hint{font-size:12px;color:var(--muted)}@media(max-width:650px){.builder{padding:16px}.block-grid{grid-template-columns:1fr}}</style></head><body class="dashboard"><main class="builder"><div class="builder-head"><div><div class="eyebrow">DESIGN / HOMEPAGE</div><h1>Visual Page Builder<span class="lime">.</span></h1><p class="builder-intro">Susun blok konten halaman utama tanpa mengedit PHP. Maksimal 8 blok; gunakan URL internal, anchor, atau URL gambar yang kamu percaya.</p></div><a class="button secondary" href="<?=e(base_url('index.php'))?>" target="_blank" rel="noopener">View website ↗</a></div><?php if($notice):?><p role="status" class="settings-note"><?=e($notice)?></p><?php endif;?><form method="post" id="builderForm"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div id="blocks"><?php foreach($blocks as $i=>$b):?><section class="block-card"><div class="builder-head"><h2>Block <?=($i+1)?></h2><button type="button" class="button secondary remove-block">Remove</button></div><div class="block-grid"><div class="field"><label>Block type</label><select name="type[]"><option value="feature" <?=$b['type']==='feature'?'selected':''?>>Feature / Hero</option><option value="text" <?=$b['type']==='text'?'selected':''?>>Text section</option><option value="image" <?=$b['type']==='image'?'selected':''?>>Image section</option><option value="cta" <?=$b['type']==='cta'?'selected':''?>>Call to action</option></select></div><div class="field"><label>Heading</label><input name="title[]" maxlength="140" value="<?=pbv($b['title']??'')?>" placeholder="Section heading"></div></div><div class="field"><label>Text</label><textarea name="text[]" maxlength="1200" placeholder="Short paragraph"><?=pbv($b['text']??'')?></textarea></div><div class="block-grid"><div class="field"><label>Button label (optional)</label><input name="button[]" maxlength="80" value="<?=pbv($b['button']??'')?>"></div><div class="field"><label>Button URL</label><input name="url[]" maxlength="500" value="<?=pbv($b['url']??'')?>" placeholder="#latest or https://…"></div></div><div class="field"><label>Image URL (optional)</label><input name="image[]" maxlength="500" value="<?=pbv($b['image']??'')?>" placeholder="/uploads/example.webp or https://…"></div></section><?php endforeach;?></div><div class="actions"><button type="button" class="button secondary" id="addBlock">＋ Add block</button><button class="button" name="action" value="save">Save homepage ↗</button><button class="button secondary" name="action" value="reset" formnovalidate>Reset default blocks</button><a class="button secondary" href="<?=e(base_url('admin/index.php'))?>">Dashboard</a></div><p class="hint">Changes apply to the public homepage after saving. Draft preview is not published until you save.</p></form></main><template id="blockTemplate"><section class="block-card"><div class="builder-head"><h2>New block</h2><button type="button" class="button secondary remove-block">Remove</button></div><div class="block-grid"><div class="field"><label>Block type</label><select name="type[]"><option value="feature">Feature / Hero</option><option value="text">Text section</option><option value="image">Image section</option><option value="cta">Call to action</option></select></div><div class="field"><label>Heading</label><input name="title[]" maxlength="140" placeholder="Section heading"></div></div><div class="field"><label>Text</label><textarea name="text[]" maxlength="1200" placeholder="Short paragraph"></textarea></div><div class="block-grid"><div class="field"><label>Button label (optional)</label><input name="button[]" maxlength="80"></div><div class="field"><label>Button URL</label><input name="url[]" maxlength="500" placeholder="#latest or https://…"></div></div><div class="field"><label>Image URL (optional)</label><input name="image[]" maxlength="500" placeholder="/uploads/example.webp or https://…"></div></section></template><script>const list=document.getElementById('blocks');function bindRemove(){list.querySelectorAll('.remove-block').forEach(b=>b.onclick=()=>{if(list.children.length>1)b.closest('.block-card').remove();else alert('Keep at least one block.');});}document.getElementById('addBlock').onclick=()=>{if(list.children.length>=8){alert('Maximum 8 blocks.');return;}list.append(document.getElementById('blockTemplate').content.cloneNode(true));bindRemove();};bindRemove();</script></body></html>
